import React, { useState } from "react";
import "./HorizontalClickableCard.scss";

export interface HorizontalClickableCardProps {
  id?: string;
  cardType?: "elevated" | "filled" | "outline";
  types?: "Card01" | "Card02";
  showImage?: boolean;
  imageUrl?: string;
  title?: string;
  subText?: string;
  description?: string;
  onCardClick?: () => void;
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent<HTMLDivElement>) => void;
  onDragEnd?: (e: React.DragEvent<HTMLDivElement>) => void;
  disabled?: boolean;
}

const HorizontalClickableCard: React.FC<HorizontalClickableCardProps> = ({
  id,
  cardType= "elevated",
  types = "Card01",
  showImage = true,
  imageUrl,
  title,
  subText,
  description,
  onCardClick,
  draggable = true,
  onDragStart,
  onDragEnd,
  disabled = false,
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [justDragged, setJustDragged] = useState(false);

  const handleDragStart = (e: React.DragEvent<HTMLDivElement>) => {
    setIsDragging(true);
    onDragStart?.(e);   
  };

  const handleDragEnd = (e: React.DragEvent<HTMLDivElement>) => {
    setIsDragging(false);
    setJustDragged(true);
    onDragEnd?.(e);
    setTimeout(() => setJustDragged(false), 100);
  };

  const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (justDragged) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    onCardClick?.();
  };

  const showImageleft = types === "Card01";

  return (
    <div
      className={`mpa-hclickcardLayoutWrapper ${disabled ? "disabled" : ""} ${isDragging ? "dragging" : ""} ${cardType} `}
      onClick={handleClick}
      role="button"
      tabIndex={0}
      draggable={draggable}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onCardClick?.();
        }
      }}
    >
      {showImage && showImageleft && (
        <div className="mpa-hclickcardImageContainer">
          <img
            src={imageUrl}
            alt={(id ?? "") + " Description of image"}
            className="mpa-hclickcardImage"
          />
        </div>
      )}

      <div className="mpa-hclickcardSupportContainer">
        <div className="mpa-hclickcardSupportTextContent">
          <div className="mpa-hclickcardSupportTitle">{title}</div>
          <div className="mpa-hclickcardSupportsubTitle">{subText}</div>
          <div className="mpa-hclickcardSupportDescription text-multiline-ellipsis">
            {description}
          </div>
        </div>
      </div>

      {showImage && !showImageleft && (
        <div className="mpa-hclickcardImageContainer">
          <img
            src={imageUrl}
            alt={(id ?? "") + " Description of image"}
            className="mpa-hclickcardImage"
          />
        </div>
      )}
    </div>
  );
};

export default HorizontalClickableCard;
